/** A marca do cald: o claudinho gota, só corpo e olhos vazados, na cor do texto. */
function caldMark(size = 20, cls = '') {
  return `<svg class="${cls}" width="${size}" height="${size}" viewBox="1 1.5 30 30" fill="currentColor" aria-hidden="true"><path fill-rule="evenodd" d="${CALD_PATH}"/></svg>`
}

